/**
 * A planet view's colour grade and focus, the last pass on its camera — CODE-SPLIT.
 *
 * A REGISTERED CHUNK MANIFEST MODULE (MANIFEST_MODULES and ALLOWLIST in
 * tooling/check-shader-imports.mjs): the import site of the pass and the
 * look-up table's texture below, loaded only by dynamic `import()` from the
 * planet view, for a world that asks for a grade or an eye high enough to
 * soften the far ground.
 *
 * One pass, last on the camera, after the exposure and the bloom: it reads the
 * finished view, softens what lies past the focus (gradeFocus.ts has the
 * arithmetic) and looks each colour up in the world's table. The focus's
 * distances come from the depth the scene was drawn with: the first pass on
 * the camera is the one the scene is drawn into, and this pass gives it a
 * depth texture where it has none, as the temporal anti-aliasing does. With
 * neither a grade nor a focus to draw, the pass is off the camera, so the
 * view is exactly as it was.
 *
 * The blur is a gather over a disc of samples, each counting only where its
 * own blur reaches the pixel, so a sharp near edge does not spill a halo over
 * the far ground behind it. The table is a strip of its blue slices; a colour
 * is read between the two slices about it.
 *
 * The world's table is fetched here, once per URL. A table that cannot be
 * fetched or read is warned about and left out: the view is drawn ungraded.
 * As eyeChunk.ts does, the pass is written in WGSL for WebGPU and GLSL for
 * WebGL2, kept in step.
 */
import { PostProcess } from '@babylonjs/core/PostProcesses/postProcess';
import { ShaderLanguage } from '@babylonjs/core/Materials/shaderLanguage';
import { ShaderStore } from '@babylonjs/core/Engines/shaderStore';
import { Constants } from '@babylonjs/core/Engines/constants';
import type { Camera } from '@babylonjs/core/Cameras/camera';
import type { Effect } from '@babylonjs/core/Materials/effect';
import type { Observer } from '@babylonjs/core/Misc/observable';
import type { Scene } from '@babylonjs/core/scene';
import type { InternalTexture } from '@babylonjs/core/Materials/Textures/internalTexture';
import type { GradeFocusFrame, GradeFocusHandle } from './planetView';
import { MAX_CUBE_SIZE, cubeStrip, maxBlurPx, parseCube, type CubeLut } from './gradeFocus';

/** The most a table's text is read to: a 64³ table, its 262,144 entries written to six places, with room for comments. */
const MAX_TABLE_BYTES = 10 * 1024 * 1024;
/** The tables kept, each a texture: a world that changes its grade often gives back the least recently drawn with. */
const MAX_TABLES = 4;

/** A response's text, or null once it runs past `max` bytes, read no further. */
async function readWithin(res: Response, max: number): Promise<string | null> {
  if (Number(res.headers.get('content-length')) > max) {
    void res.body?.cancel().catch(() => {});
    return null;
  }
  if (!res.body) return '';
  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let text = '';
  let total = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) return text + decoder.decode();
    total += value.byteLength;
    if (total > max) {
      void reader.cancel().catch(() => {});
      return null;
    }
    text += decoder.decode(value, { stream: true });
  }
}

/** Samples across the blur's disc, besides the pixel's own. */
const BLUR_SAMPLES = 12;
/** The blur's radius, in pixels, below which the pixel is left as it is. */
const BLUR_LEAST_PX = 0.25;
/** The golden angle, which spreads the samples evenly over the disc. */
const GOLDEN_ANGLE = 2.39996323;

const f = (x: number) => (Number.isInteger(x) ? `${x}.0` : String(x));

// ---- GLSL (WebGL) ----

const GRADE_FOCUS_GLSL = `
varying vec2 vUV;
uniform sampler2D textureSampler;
uniform sampler2D lutSampler;
uniform highp sampler2D depthSampler;
uniform float graded;
uniform float lutSize;
uniform vec3 domainMin;
uniform vec3 domainMax;
uniform float focusStrength;
uniform float focusM;
uniform float maxPx;
uniform vec2 depthAB;
uniform vec2 depthNdc;
uniform vec2 texel;
// Metres from the eye, along its line, of what was drawn at uv: the projection's depth undone. Nothing drawn is far off.
float depthAt(vec2 uv) {
  ivec2 size = textureSize(depthSampler, 0);
  ivec2 q = clamp(ivec2(uv * vec2(size)), ivec2(0), size - 1);
  float ndc = texelFetch(depthSampler, q, 0).r * depthNdc.x + depthNdc.y;
  float den = ndc - depthAB.x;
  float z = abs(den) > 1e-7 ? depthAB.y / den : 1e30;
  return z > 0.0 ? z : 1e30;
}
float blurPx(vec2 uv) {
  float z = depthAt(uv);
  return z > focusM ? (1.0 - focusM / z) * focusStrength * maxPx : 0.0;
}
vec3 grade(vec3 c) {
  vec3 p = clamp((c - domainMin) / (domainMax - domainMin), 0.0, 1.0) * (lutSize - 1.0);
  float b0 = min(floor(p.b), lutSize - 2.0);
  float w = lutSize * lutSize;
  vec2 uv = vec2((b0 * lutSize + p.r + 0.5) / w, (p.g + 0.5) / lutSize);
  vec3 lo = texture2D(lutSampler, uv).rgb;
  vec3 hi = texture2D(lutSampler, uv + vec2(lutSize / w, 0.0)).rgb;
  return mix(lo, hi, p.b - b0);
}
void main(void) {
  vec3 c = texture2D(textureSampler, vUV).rgb;
  if (focusStrength > 0.0) {
    float r = blurPx(vUV);
    if (r > ${f(BLUR_LEAST_PX)}) {
      vec3 sum = c;
      float total = 1.0;
      for (int i = 0; i < ${BLUR_SAMPLES}; i++) {
        float a = float(i) * ${f(GOLDEN_ANGLE)};
        float d = sqrt((float(i) + 0.5) / ${f(BLUR_SAMPLES)}) * r;
        vec2 uv = vUV + vec2(cos(a), sin(a)) * d * texel;
        float w = clamp(blurPx(uv) - d + 1.0, 0.0, 1.0);
        sum += texture2D(textureSampler, uv).rgb * w;
        total += w;
      }
      c = sum / total;
    }
  }
  if (graded > 0.5) c = grade(clamp(c, 0.0, 1.0));
  gl_FragColor = vec4(c, 1.0);
}`;

// ---- WGSL (WebGPU): the same pass, in Babylon's WGSL post-process dialect. ----

const GRADE_FOCUS_WGSL = `
varying vUV: vec2f;
var textureSamplerSampler: sampler;
var textureSampler: texture_2d<f32>;
var lutSamplerSampler: sampler;
var lutSampler: texture_2d<f32>;
var depthSampler: texture_depth_2d;
uniform graded: f32;
uniform lutSize: f32;
uniform domainMin: vec3f;
uniform domainMax: vec3f;
uniform focusStrength: f32;
uniform focusM: f32;
uniform maxPx: f32;
uniform depthAB: vec2f;
uniform depthNdc: vec2f;
uniform texel: vec2f;
fn depthAt(uv: vec2f) -> f32 {
  let size = vec2i(textureDimensions(depthSampler, 0));
  let q = clamp(vec2i(uv * vec2f(size)), vec2i(0), size - 1);
  let ndc = textureLoad(depthSampler, q, 0) * uniforms.depthNdc.x + uniforms.depthNdc.y;
  let den = ndc - uniforms.depthAB.x;
  var z = 1e30;
  if (abs(den) > 1e-7) { z = uniforms.depthAB.y / den; }
  if (z <= 0.0) { z = 1e30; }
  return z;
}
fn blurPx(uv: vec2f) -> f32 {
  let z = depthAt(uv);
  if (z <= uniforms.focusM) { return 0.0; }
  return (1.0 - uniforms.focusM / z) * uniforms.focusStrength * uniforms.maxPx;
}
fn grade(c: vec3f) -> vec3f {
  let n = uniforms.lutSize;
  let p = clamp((c - uniforms.domainMin) / (uniforms.domainMax - uniforms.domainMin), vec3f(0.0), vec3f(1.0)) * (n - 1.0);
  let b0 = min(floor(p.b), n - 2.0);
  let w = n * n;
  let uv = vec2f((b0 * n + p.r + 0.5) / w, (p.g + 0.5) / n);
  let lo = textureSampleLevel(lutSampler, lutSamplerSampler, uv, 0.0).rgb;
  let hi = textureSampleLevel(lutSampler, lutSamplerSampler, uv + vec2f(n / w, 0.0), 0.0).rgb;
  return mix(lo, hi, p.b - b0);
}
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
  var c = textureSampleLevel(textureSampler, textureSamplerSampler, input.vUV, 0.0).rgb;
  if (uniforms.focusStrength > 0.0) {
    let r = blurPx(input.vUV);
    if (r > ${f(BLUR_LEAST_PX)}) {
      var sum = c;
      var total = 1.0;
      for (var i = 0; i < ${BLUR_SAMPLES}; i++) {
        let a = f32(i) * ${f(GOLDEN_ANGLE)};
        let d = sqrt((f32(i) + 0.5) / ${f(BLUR_SAMPLES)}) * r;
        let uv = input.vUV + vec2f(cos(a), sin(a)) * d * uniforms.texel;
        let w = clamp(blurPx(uv) - d + 1.0, 0.0, 1.0);
        sum += textureSampleLevel(textureSampler, textureSamplerSampler, uv, 0.0).rgb * w;
        total += w;
      }
      c = sum / total;
    }
  }
  if (uniforms.graded > 0.5) { c = grade(clamp(c, vec3f(0.0), vec3f(1.0))); }
  fragmentOutputs.color = vec4f(c, 1.0);
}`;

const SOURCES = {
  planetGradeFocus: [GRADE_FOCUS_GLSL, GRADE_FOCUS_WGSL],
} as const;

/** The pass's source for the engine: WGSL on WebGPU, GLSL otherwise. */
export function gradeFocusShaderLanguage(engineKind?: string): ShaderLanguage {
  return engineKind === 'webgpu' ? ShaderLanguage.WGSL : ShaderLanguage.GLSL;
}

export function createGradeFocus(
  scene: Scene,
  camera: Camera,
  opts: { engineKind?: string; fetchImpl: (url: string) => Promise<Response>; warn: (name: string, detail: string) => void },
): GradeFocusHandle {
  const engine = scene.getEngine();
  const language = gradeFocusShaderLanguage(opts.engineKind);
  const wgsl = language === ShaderLanguage.WGSL;
  for (const [name, [glsl, wgslSource]] of Object.entries(SOURCES)) {
    const store = wgsl ? ShaderStore.ShadersStoreWGSL : ShaderStore.ShadersStore;
    store[`${name}PixelShader`] ??= wgsl ? wgslSource : glsl;
  }

  // A texture of raw bytes, as the engine makes one, bound to the pass as it is: no texture class is imported, since each
  // one this chunk would share with the others splits a chunk of the main bundle. Its edges are never read past (every
  // look-up lands within its slice's row), so how it wraps does not matter.
  const rawTexture = (pixels: Uint8Array, width: number, height: number, sampling: number): InternalTexture =>
    engine.createRawTexture(pixels, width, height, Constants.TEXTUREFORMAT_RGBA, false, false, sampling);

  // The tables, by URL: fetched once each, a texture once read, or null where it could not be. In the order last drawn
  // with, so that past MAX_TABLES the one given back is the one least recently drawn with.
  const tables = new Map<string, { lut: CubeLut; texture: InternalTexture } | null | 'loading'>();
  const keepWithin = () => {
    for (const [url, t] of tables) {
      if (tables.size <= MAX_TABLES) return;
      if (t === 'loading') continue;
      t?.texture.dispose();
      tables.delete(url);
    }
  };
  let gone = false;
  const fetchTable = (url: string) => {
    tables.set(url, 'loading');
    void (async () => {
      let reason: string;
      try {
        const res = await opts.fetchImpl(url);
        const text = res.ok ? await readWithin(res, MAX_TABLE_BYTES) : undefined;
        if (text === null) reason = `larger than ${MAX_TABLE_BYTES} bytes, the most a ${MAX_CUBE_SIZE}³ table takes`;
        else if (text !== undefined) {
          const read = parseCube(text);
          if (read.ok) {
            if (gone) return;
            const strip = cubeStrip(read.lut);
            const texture = rawTexture(strip.pixels, strip.width, strip.height, Constants.TEXTURE_BILINEAR_SAMPLINGMODE);
            tables.set(url, { lut: read.lut, texture });
            keepWithin();
            return;
          }
          reason = read.reason;
        } else reason = `HTTP ${res.status}`;
      } catch (err) {
        reason = String(err);
      }
      if (gone) return;
      tables.set(url, null);
      keepWithin();
      opts.warn('veml:planet:grade-unavailable', `${url}: ${reason}`);
    })();
  };
  // Bound where no table is: the pass always has one to read.
  const neutral = rawTexture(new Uint8Array([255, 255, 255, 255]), 1, 1, Constants.TEXTURE_NEAREST_SAMPLINGMODE);

  const pass = new PostProcess('planetGradeFocus', 'planetGradeFocus', {
    engine,
    size: 1,
    uniforms: ['graded', 'lutSize', 'domainMin', 'domainMax', 'focusStrength', 'focusM', 'maxPx', 'depthAB', 'depthNdc', 'texel'],
    samplers: ['lutSampler', 'depthSampler'],
    samplingMode: Constants.TEXTURE_BILINEAR_SAMPLINGMODE,
    shaderLanguage: language,
  });
  // It writes every pixel it draws: nothing to clear.
  pass.autoClear = false;
  let attached = false;
  let table: { lut: CubeLut; texture: InternalTexture } | null = null;
  let focus: GradeFocusFrame['focus'] = null;

  // The first pass on the camera is the one the scene is drawn into: it keeps the scene's depth, as a texture to read.
  let hooked: { pp: PostProcess; observer: Observer<Camera> } | null = null;
  const firstPass = (): PostProcess | null => camera._postProcesses.find((p): p is PostProcess => !!p) ?? null;
  const giveDepth = (pp: PostProcess) => {
    const target = pp.inputTexture;
    if (!target || target.depthStencilTexture || target.width <= 0) return;
    try {
      const stencil = engine.isStencilEnable;
      target.createDepthStencilTexture(0, false, stencil, 1, stencil ? Constants.TEXTUREFORMAT_DEPTH24_STENCIL8 : Constants.TEXTUREFORMAT_DEPTH32_FLOAT);
    } catch {
      /* an engine without depth textures: nothing is softened */
    }
  };
  const unhook = () => {
    if (hooked) hooked.pp.onActivateObservable.remove(hooked.observer);
    hooked = null;
  };
  const hookDepth = () => {
    const first = attached ? firstPass() : null;
    if (hooked?.pp === first) return;
    unhook();
    if (first) hooked = { pp: first, observer: first.onActivateObservable.add(() => giveDepth(first)) };
  };
  // Last on the camera, after every pass there is and any made later (the eye's are made anew as it changes).
  const placeLast = () => {
    if (!attached) return;
    const active = camera._postProcesses.filter((p) => p !== null);
    if (active[active.length - 1] !== pass) {
      const i = camera._postProcesses.indexOf(pass);
      if (i >= 0) camera._postProcesses.splice(i, 1);
      camera._postProcesses.push(pass);
    }
    hookDepth();
  };
  const ordering: Observer<Camera> = scene.onBeforeCameraRenderObservable.add((cam) => {
    if (cam === camera) placeLast();
  });

  pass.onApplyObservable.add((effect: Effect) => {
    const depth = firstPass()?.inputTexture?.depthStencilTexture ?? null;
    if (depth) effect._bindTexture('depthSampler', depth);
    const graded = table !== null;
    effect._bindTexture('lutSampler', table?.texture ?? neutral);
    effect.setFloat('graded', graded ? 1 : 0);
    effect.setFloat('lutSize', table?.lut.size ?? 2);
    const lo = table?.lut.domainMin ?? [0, 0, 0];
    const hi = table?.lut.domainMax ?? [1, 1, 1];
    effect.setFloat3('domainMin', lo[0], lo[1], lo[2]);
    effect.setFloat3('domainMax', hi[0], hi[1], hi[2]);
    effect.setFloat('focusStrength', focus && depth ? focus.strength : 0);
    effect.setFloat('focusM', focus?.distanceM ?? 0);
    effect.setFloat('maxPx', maxBlurPx(pass.height));
    // The projection's depth, z = (A·d + B) / d, undone per pixel; 0 to 1 on WebGPU, -1 to 1 on WebGL.
    const m = camera.getProjectionMatrix().m;
    effect.setFloat2('depthAB', m[10]!, m[14]!);
    if (engine.isNDCHalfZRange) effect.setFloat2('depthNdc', 1, 0);
    else effect.setFloat2('depthNdc', 2, -1);
    effect.setFloat2('texel', 1 / Math.max(1, pass.width), 1 / Math.max(1, pass.height));
  });

  return {
    update(frame) {
      let next: typeof table = null;
      if (frame.grade) {
        const known = tables.get(frame.grade);
        if (known === undefined) fetchTable(frame.grade);
        else {
          // Drawn with now: the last to be given back.
          tables.delete(frame.grade);
          tables.set(frame.grade, known);
          if (known !== 'loading' && known !== null) next = known;
        }
      }
      table = next;
      focus = frame.focus && frame.focus.strength > 0 ? frame.focus : null;
      const want = table !== null || focus !== null;
      if (want && !attached) {
        camera.attachPostProcess(pass);
        attached = true;
      } else if (!want && attached) {
        camera.detachPostProcess(pass);
        attached = false;
      }
      placeLast();
      if (!attached) unhook();
    },
    dispose() {
      gone = true;
      scene.onBeforeCameraRenderObservable.remove(ordering);
      unhook();
      pass.dispose(camera);
      attached = false;
      neutral.dispose();
      for (const t of tables.values()) if (t && t !== 'loading') t.texture.dispose();
      tables.clear();
    },
  };
}
